$tabs = ['inicio' => 'Resumen', 'perfil' => 'Mi perfil', 'atestados' => 'Atestados', 'galeria' => 'Galería', 'blog' => 'Blog'];
$tab = (string) ($_GET['tab'] ?? 'inicio');
