$notice = take_flash();
function admin_input(string $name, string $label, string $value = '', string $type = 'text', int $maxlength = 180, bool $required = false): void
{
    $id = 'field-' . $name . '-' . bin2hex(random_bytes(3));
    echo '<div class="form-field"><label for="' . e($id) . '">' . e($label) . '</label><input id="' . e($id) . '" name="' . e($name) . '" type="' . e($type) . '" value="' . e($value) . '" maxlength="' . $maxlength . '" ' . ($required ? 'required' : '') . '></div>';
}
function admin_textarea(string $name, string $label, string $value = '', bool $required = false): void
{
    $id = 'field-' . $name . '-' . bin2hex(random_bytes(3));
    echo '<div class="form-field full"><label for="' . e($id) . '">' . e($label) . '</label><textarea id="' . e($id) . '" name="' . e($name) . '" ' . ($required ? 'required' : '') . '>' . e($value) . '</textarea></div>';
}
function upload_field(string $label = 'Imagen', bool $required = false): void
{
    echo '<div class="form-field"><label>' . e($label) . '</label><input name="image" type="file" accept="image/jpeg,image/png,image/webp" ' . ($required ? 'required' : '') . '><small>JPEG, PNG o WebP · Máximo 5 MB</small></div>';
}
?>
